const routes=[{id:'9',name:'Walmart – Galleria',area:'urban',places:'Shopping · Greater Johnstown',stops:['Johnstown Transit Center','Illustrative neighborhood stop','Walmart','Galleria']},{id:'12',name:'Hystone – Westwood',area:'urban',places:'Neighborhood connections · Greater Johnstown',stops:['Johnstown Transit Center','Illustrative neighborhood stop','Hystone','Westwood']},{id:'18',name:'Downtown Shuttle',area:'urban',places:'Downtown connections · Johnstown',stops:['Johnstown Transit Center','Illustrative downtown stop','Illustrative civic stop','Johnstown Transit Center']},{id:'21',name:'Windber',area:'urban',places:'Community connections · Windber',stops:['Johnstown Transit Center','Illustrative connecting stop','Windber']},{id:'+',name:'Northern Cambria County',area:'rural',places:'CamTran+ · Explore rural service',stops:[]}];
const $=s=>document.querySelector(s);let filter='all',lang='en';const modal=$('#modal');let returnFocus;
function openModal(html){returnFocus=document.activeElement;$('#modal-body').innerHTML=html;modal.showModal();$('#close-modal').focus()}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('close',()=>returnFocus?.focus());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function renderRoutes(){const q=$('#route-search').value.trim().toLowerCase();const shown=routes.filter(r=>(filter==='all'||r.area===filter)&&`${r.id} ${r.name} ${r.places}`.toLowerCase().includes(q));$('#route-list').innerHTML=shown.length?shown.map(r=>`<button class="route-row" data-route="${r.id}"><span class="route-number">${r.id}</span><div><h3>${r.name}</h3><p>${r.places}</p></div><span class="route-type">${r.area==='urban'?'URBAN':'CAMTRAN+'}</span><b aria-hidden="true">↗</b></button>`).join(''):'<p class="no-results">No matching routes. Try “Galleria”, “18”, or clear your search.</p>';$('#route-count').textContent=`${shown.length} route examples shown · Prototype route directory`;document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>routeDetail(b.dataset.route))}
function routeDetail(id){const r=routes.find(r=>r.id===id);if(r.area==='rural'){openModal('<h2>Explore CamTran+</h2><p>Rural service connects northern Cambria County. This prototype links to the official directory instead of inventing route numbers or service times.</p><a href="https://www.camtranbus.com/schedules/camtran-plus-rural-routes/">View official rural schedules ↗</a>');return}openModal(`<p class="eyebrow">URBAN / ROUTE ${r.id}</p><h2>${r.name}</h2><p class="preview-notice">Demonstration only. The stop sequence and times below are illustrative and must not be used for travel.</p><div class="filters"><button class="selected" id="outbound">Outbound</button><button id="inbound">Inbound</button></div><ol class="stop-list" id="stop-sequence">${r.stops.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Sample weekday timetable</h3><table><caption>Illustrative departures, not an operating schedule</caption><thead><tr><th>Trip</th><th>First stop</th><th>Last stop</th></tr></thead><tbody><tr><td>Sample 1</td><td>9:00 AM</td><td>9:35 AM</td></tr><tr><td>Sample 2</td><td>10:00 AM</td><td>10:35 AM</td></tr></tbody></table><a href="https://www.camtranbus.com/schedules/camtran-urban-routes/">Official schedules and downloadable PDFs ↗</a>`);['outbound','inbound'].forEach(dir=>$('#'+dir).onclick=()=>{const stops=dir==='inbound'?[...r.stops].reverse():r.stops;$('#stop-sequence').innerHTML=stops.map(s=>`<li>${s}</li>`).join('');['outbound','inbound'].forEach(d=>$('#'+d).classList.toggle('selected',d===dir))})}
$('#route-search').oninput=renderRoutes;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});renderRoutes()});renderRoutes();
function renderArrivals(){const id=$('#tracker-route').value;const r=routes.find(r=>r.id===id);$('#arrivals').innerHTML=[6,26].map((m,i)=>`<div class="arrival"><span class="route-number">${id}</span><div><strong>${r.name}</strong><small>Sample departure ${i+1}</small></div><div class="arrival-time">${m}<small>DEMO MIN</small></div></div>`).join('')}
$('#tracker-route').onchange=renderArrivals;renderArrivals();
let tab='plan';document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',t===b));$('#trip-form').hidden=tab!=='plan';$('#tool-result').innerHTML=tab==='track'?'<p>Select a route in the arrival preview below. <a class="text-link dark" href="#tracker">Explore bus tracking →</a></p>':tab==='find'?'<p>Search by route number or destination below. <a class="text-link dark" href="#routes">Browse route examples →</a></p>':''};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')];const next=tabs[(tabs.indexOf(b)+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.focus();next.click()}}});
$('#swap').onclick=()=>{const a=$('#origin').value;$('#origin').value=$('#destination').value;$('#destination').value=a};
$('#trip-form').onsubmit=e=>{e.preventDefault();const a=$('#origin').value,b=$('#destination').value;if(a===b){$('#tool-result').innerHTML='<p>Please choose different starting and ending locations.</p>';return}const id=(a==='Westwood'||b==='Westwood')?'12':'9';$('#tool-result').innerHTML=`<p><strong>Sample journey: ${a} → ${b}</strong><br>Route ${id} · Illustrative connection only. Not a calculated itinerary. ${$('#departure').selectedIndex?'Tomorrow morning sample selected.':'Leave-now sample selected.'} <button class="text-link dark" id="trip-route">Explore route ${id} →</button></p>`;$('#trip-route').onclick=()=>routeDetail(id)};
function savedAlert(){try{return JSON.parse(localStorage.getItem('camtran-demo-alert')||'null')}catch{return null}}const alert=savedAlert();if(alert&&typeof alert.text==='string')$('#alert-text').textContent='Sample: '+alert.text;
$('#alert-details').onclick=()=>{openModal('<h2>Service notice preview</h2><p class="preview-notice">This is a sample notice, not an active service alert.</p><p id="notice-copy"></p><h3>Before you travel</h3><p>Check the official website or live tracker for current operating information.</p><a href="https://www.camtranbus.com/">Visit the official CamTran website ↗</a>');$('#notice-copy').textContent=alert?.text||'Example: A downtown stop has temporarily moved. Production notices would include affected routes, accessible boarding directions, and start and end dates.'};
$('#discounts').onclick=()=>openModal('<h2>A fare that fits.</h2><p>CamTran publishes fare options for students, seniors, children, and riders eligible for reduced fares. Requirements and documentation vary by program.</p><p>Confirm eligibility and current prices directly with CamTran before travel.</p><a href="https://www.camtranbus.com/fares/camtran-fares/">Explore official fares and discounts ↗</a>');
const services={paratransit:['ADA & paratransit','Explore eligibility, application requirements, service boundaries, and reservations with CamTran.','https://www.camtranbus.com/disability-services/'],shared:['Reserve-A-Ride','Learn about shared ride service, eligibility, reservations, and applicable fares.','https://www.camtranbus.com/services/reserve-a-ride/'],medical:['Medical transportation','Explore the Medical Assistance Transportation Program and its application process.','https://www.camtranbus.com/matp-2/']};
document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{const s=services[b.dataset.service];openModal(`<h2>${s[0]}</h2><p>${s[1]}</p><ol><li>Review the service and eligibility information.</li><li>Contact CamTran for help choosing the right program.</li><li>Complete the official application, if required.</li></ol><p>This demonstration does not determine eligibility or collect applications.</p><a href="${s[2]}">Continue to official program information ↗</a>`) });
$('#calendar').onclick=()=>openModal('<h2>Community calendar</h2><p class="preview-notice">Sample events for demonstrating the calendar interface.</p><details open><summary>October 20 · Community listening session</summary><p>Example event · 1:30 PM · Transit Center<br>Discussion of rider needs and connections.</p></details><details><summary>November 5 · New rider orientation</summary><p>Example event · 10:00 AM · Learn how to read schedules and pay fares.</p></details>');
const es={navRoutes:'Rutas y horarios',navFares:'Tarifas y pases',navRide:'Servicios',navAbout:'Comunidad',track:'Rastrear autobús ↗',alertLabel:'AVISO DE SERVICIO',details:'Ver detalles →',eyebrow:'CONECTAMOS EL CONDADO DE CAMBRIA.',headline:'Tu día.<br>Tu destino.<br><em>Tu viaje.</em>',description:'Desde tu viaje diario hasta tu próxima aventura. Te ayudamos a encontrar una mejor manera de llegar.',heroFoot:'Conectamos a nuestros vecinos.<br>Unimos a nuestras comunidades.',busCard:'Lo bueno está en camino.',busSub:'Vamos a tu destino.',plan:'↗ Planificar viaje',trackTab:'◉ Rastrear autobús',findTab:'≡ Buscar ruta',sample:'DEMOSTRACIÓN · DATOS DE EJEMPLO',from:'Origen',to:'Destino',when:'Cuándo',findTrip:'Buscar mi viaje →',routesEye:'UNA RUTA PARA TU DÍA',routesTitle:'¿A dónde vas?',routesIntro:'Encuentra tu conexión en Johnstown<br>y el norte del condado de Cambria.',trackerTitle:'Tu próximo autobús,<br>de un vistazo.',trackerText:'Selecciona una ruta para explorar la vista de llegadas de ejemplo.',faresTitle:'Tu viaje. Tu forma de pagar.',servicesTitle:'Cada pasajero cuenta.'};const en={};document.querySelectorAll('[data-i]').forEach(el=>en[el.dataset.i]=el.innerHTML);
$('#language').onclick=()=>{lang=lang==='en'?'es':'en';document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>el.innerHTML=(lang==='es'?es:en)[el.dataset.i]);$('#language').setAttribute('aria-label',lang==='es'?'Switch to English':'Switch to Spanish');$('#alert-text').textContent=lang==='es'?'Ejemplo: Parada reubicada en el centro. Consulta tu ruta antes de viajar.':'Sample: '+(alert?.text||'Downtown stop relocation. Check your route before traveling.');$('#route-search').placeholder=lang==='es'?'Buscar número de ruta o destino':'Search route number or destination';$('#language').textContent=lang==='es'?'EN / ES':'ES / EN'};


if(alert?.priority==='Emergency'){document.querySelector('.alert').style.background='#ffe0d5';document.querySelector('[data-i=alertLabel]').textContent='EMERGENCY DEMO'}; if(alert?.title)document.querySelector('#alert-text').textContent='Sample: '+alert.title+' — '+alert.text;

